import { promises as fs } from 'fs'
import Home from './page'
import type { ProductGroup } from '@/lib/types'

vi.mock('@/components/header', () => ({
  __esModule: true,
  default: () => <div data-testid="header" />,
}))

vi.mock('@/components/block', () => ({
  __esModule: true,
  default: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
}))

describe('timing probe', () => {
  it('splits the cost', async () => {
    const t0 = performance.now()
    const catalogue: ProductGroup[] = JSON.parse(
      await fs.readFile(`${process.cwd()}/public/categories.json`, 'utf8'),
    )
    const product = catalogue[0].products[0]
    const t1 = performance.now()
    const tree = await Home()
    const t2 = performance.now()
    render(tree)
    const t3 = performance.now()
    screen.getByRole('link', { name: product.name })
    const t4 = performance.now()
    // second pass, same file: no import cost left
    const tree2 = await Home()
    render(tree2)
    const t5 = performance.now()
    screen.getAllByRole('link', { name: product.name })
    const t6 = performance.now()
    console.log(
      `PROBE read=${(t1 - t0).toFixed(0)} Home()=${(t2 - t1).toFixed(0)} render=${(t3 - t2).toFixed(0)} getByRole=${(t4 - t3).toFixed(0)} render2=${(t5 - t4).toFixed(0)} getByRole2=${(t6 - t5).toFixed(0)}`,
    )
  }, 60_000)
})

