import { describe, it, expect } from 'vitest'

/**
 * The suite's own flake policy, read back from the runner.
 *
 * `task.timeout` and `task.retry` are what the runner will enforce on this
 * test, resolved from the config it actually loaded. A regex over
 * `vitest.config.mts` would instead assert that a line is written there, and
 * the two come apart in the case worth catching: #281 showed this config file
 * being loaded three different ways, and a config vitest fails to load leaves
 * the implicit 5000ms in place with the declaration still sitting in the file.
 */

// Measured on an idle 24-core machine: the slowest test in this suite is
// `src/app/page.test.tsx` at 1.6-2.0s, and nine others sit between 0.6s and
// 1.2s. Against vitest's implicit 5000ms that is under 3x of headroom, and #283
// recorded two files crossing it during a full run that took roughly 4-5x
// longer per test than an idle one. This floor is 10x the slowest test.
const MIN_TEST_TIMEOUT_MS = 20_000

function retryCount(retry: number | { count?: number } | undefined): number {
  return typeof retry === 'object' ? (retry.count ?? 0) : (retry ?? 0)
}

describe('runner budget', () => {
  it('gives a test more room than the implicit 5s default', ({ task }) => {
    expect(task.timeout).toBeGreaterThanOrEqual(MIN_TEST_TIMEOUT_MS)
  })

  // The same policy `playwright.config.ts` states for the journeys, for the
  // same reason: a retried failure is a failure that gets ignored. #283 exists
  // because a real timeout went green on the next run; retries would have made
  // that the permanent outcome rather than a finding.
  it('retries nothing', ({ task }) => {
    expect(retryCount(task.retry)).toBe(0)
  })
})

