import { describe, it, expect, vi } from 'vitest'
import { render, screen } from '@testing-library/react'
import { promises as fs } from 'fs'
import Home from './page'
import type { ProductGroup } from '@/lib/types'

vi.mock('@/components/header', () => ({
  __esModule: true,
  default: () => <div data-testid="header" />,
}))

vi.mock('@/components/block', () => ({
  __esModule: true,
  default: ({ children }: { children: React.ReactNode }) => <div>{children}</div>,
}))

describe('query cost probe', () => {
  it('compares getByRole against a located element', async () => {
    const catalogue: ProductGroup[] = JSON.parse(
      await fs.readFile(`${process.cwd()}/public/categories.json`, 'utf8'),
    )
    const product = catalogue[0].products[0]
    const { container } = render(await Home())

    const a0 = performance.now()
    screen.getByRole('link', { name: product.name })
    const a1 = performance.now()

    const b0 = performance.now()
    const link = container.querySelector(`a[href="/products/${product.slug}"]`)
    expect(link).toHaveAccessibleName(product.name)
    const b1 = performance.now()

    // does the cheap form still catch the doubled-name defect?
    const img = link!.querySelector('img')!
    img.setAttribute('alt', product.name)
    let caught = false
    try {
      expect(link).toHaveAccessibleName(product.name)
    } catch {
      caught = true
    }
    img.setAttribute('alt', '')

    console.log(
      `PROBE2 getByRole=${(a1 - a0).toFixed(0)}ms located+toHaveAccessibleName=${(b1 - b0).toFixed(0)}ms doubledNameCaught=${caught}`,
    )
  }, 60_000)
})

